def item=(value)
  return if value && !GameData::Item.exists?(value)
  @item = (value) ? GameData::Item.get(value).id : value
end

def mail=(mail)
  if !mail.nil? && !mail.is_a?(Mail)
    raise ArgumentError, _INTL("Invalid value {1} given", mail.inspect)
  end
  @mail = mail
end
